import base64, hashlib, json, os, re, shutil, signal, stat, subprocess, sys, time, traceback
from pathlib import Path
from datetime import datetime, timezone

ROOT = Path('/home/ubuntu/live/hivezilla-validator-20260930')
DONOR = Path('/home/ubuntu/benchmarks/bank-connection-idle-20261018-2f3cbe5e/provider')
DONOR_MANIFEST = ROOT / 'releases/bank-connection-idle-20261018-2f3cbe5e-73506f06cdc6/SOURCE.json'
DONOR_SHA = '58ca93f632098973f8353632e87415a2dc9e01a98bedf786c453ec3178fae41b'
PATCH = base64.b64decode('')
PATCH_MANIFEST_BYTES = base64.b64decode('')
PATCH_SHA = '92f2376d361a62b4e34f4671e93c1b5f70bcf1b1f95c9c8b653a3c70c94c708e'
PATCH_MANIFEST_SHA = 'e8dfe7b56cbfe332380217100dab0fa4fae9ce4e2c1ab5ae2e3d7099a4e23c5b'
STAGE = Path('/home/ubuntu/benchmarks/publisher-status-20261018-' + PATCH_SHA[:8])
PROVIDER = STAGE / 'provider'
TARGET = STAGE / 'target'
REPORT = ROOT / 'reports/native-recovery-20261018/recurrence/evening-20261018/publisher-status'
TOOL_BIN = Path('/home/ubuntu/.rustup/toolchains/1.98.0-x86_64-unknown-linux-gnu/bin')
ADMISSION = 601295421440
BASE_RESERVE = 566935683072
TARGET_BUDGET = 32 * 1024**3
FLAGS = '-C target-cpu=x86-64 -C target-feature=+aes,+sse2'
state = {'schema':'blockzilla-publisher-status-build-v1','state':'STAGING',
         'started_unix_ms':time.time_ns()//1000000,'stage':str(STAGE),
         'report':str(REPORT),'patch_sha256':PATCH_SHA,'patch_manifest_sha256':PATCH_MANIFEST_SHA,
         'donor_manifest_sha256':DONOR_SHA,'tests_passed':False,'tests_count':0,'service_operations':[],
         'retirement_cap_changes':[],'build_flags':FLAGS,'commands':[],
         'target_budget_bytes':TARGET_BUDGET,'admission_minimum_free_bytes':ADMISSION}

def digest(path):
    with path.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()

def save(path, value):
    body=(json.dumps(value,indent=2,sort_keys=True)+'\n').encode()
    temp=path.with_name(path.name+'.new')
    with temp.open('wb') as f:f.write(body);f.flush();os.fsync(f.fileno())
    os.replace(temp,path)

def publish(**fields):
    state.update(fields,updated_unix_ms=time.time_ns()//1000000)
    state['updated_utc']=datetime.fromtimestamp(state['updated_unix_ms']/1000,timezone.utc).isoformat(timespec='milliseconds')
    save(REPORT/'BUILD.json',state)
    print(json.dumps({k:state.get(k) for k in ('state','updated_unix_ms','target_allocated_bytes','free_disk_bytes','tests_passed','binary_sha256','release')}),flush=True)

def free():
    s=os.statvfs(ROOT);return s.f_bavail*s.f_frsize

def temporary_archives():
    return [p.name for p in (ROOT/'snapshots').glob('tmp-snapshot-archive-*') if p.is_file()]

def target_bytes():
    attempts=[]
    for attempt in range(5):
        p=subprocess.run(['ionice','-c3','nice','-n','19','du','-s','-x','--block-size=1',str(TARGET)],capture_output=True,text=True)
        if p.returncode==0:
            if attempts:state.setdefault('transient_target_scan_retries',[]).append({'unix_ms':time.time_ns()//1000000,'attempts':attempts})
            return int(p.stdout.split()[0])
        details={'returncode':p.returncode,'stderr':p.stderr[:4096]}
        attempts.append(details)
        lines=p.stderr.splitlines()
        if p.returncode!=1 or not lines or not all('No such file or directory' in line and str(TARGET) in line for line in lines):
            raise RuntimeError('target_allocation_scan_failed:'+json.dumps(details))
        time.sleep(0.1)
    raise RuntimeError('target_allocation_scan_transient_retries_exhausted:'+json.dumps(attempts))

def check_guard():
    used=target_bytes();available=free();temps=temporary_archives()
    state.update(target_allocated_bytes=used,free_disk_bytes=available,active_temporary_archive_count=len(temps))
    if used>TARGET_BUDGET:raise RuntimeError('target_budget_exceeded')
    if available<=BASE_RESERVE:raise RuntimeError('runtime_disk_reserve_guard')

def terminate_child(proc):
    if proc.poll() is not None:return
    os.killpg(proc.pid,signal.SIGTERM)
    try:proc.wait(timeout=10)
    except subprocess.TimeoutExpired:
        os.killpg(proc.pid,signal.SIGKILL);proc.wait(timeout=10)

def run_phase(phase, args, log_name, env, *, cwd=None, expected_returncode=0, red=False):
    command=['ionice','-c3','nice','-n','19',str(TOOL_BIN/'cargo'),*args]
    entry={'phase':phase,'argv':command,'cwd':str(cwd or PROVIDER/'hivezilla/stream-relay'),'started_unix_ms':time.time_ns()//1000000,'log':str(REPORT/log_name)}
    if red:state['red_comparison_command']=entry
    else:state['commands'].append(entry)
    publish(state=phase)
    with (REPORT/log_name).open('xb') as log:
        proc=subprocess.Popen(command,cwd=cwd or PROVIDER/'hivezilla/stream-relay',env=env,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
        last_report=0
        try:
            while proc.poll() is None:
                check_guard()
                if time.monotonic()-last_report>=30:publish();last_report=time.monotonic()
                time.sleep(5)
        except BaseException:
            terminate_child(proc);raise
        entry.update(returncode=proc.returncode,completed_unix_ms=time.time_ns()//1000000)
    entry['log_sha256']=digest(REPORT/log_name)
    if entry['returncode']!=expected_returncode:raise RuntimeError(phase.lower()+'_unexpected_returncode')
    check_guard()

def main():
    if hashlib.sha256(PATCH).hexdigest()!=PATCH_SHA:raise RuntimeError('patch_hash_mismatch')
    if hashlib.sha256(PATCH_MANIFEST_BYTES).hexdigest()!=PATCH_MANIFEST_SHA:raise RuntimeError('patch_manifest_hash_mismatch')
    if STAGE.exists() or (REPORT/'BUILD.json').exists():raise RuntimeError('stage_or_build_receipt_already_exists')
    if temporary_archives():raise RuntimeError('admission_active_snapshot_archive')
    available=free()
    if available<ADMISSION:raise RuntimeError('admission_free_disk_too_low')
    if digest(DONOR_MANIFEST)!=DONOR_SHA:raise RuntimeError('donor_manifest_changed')
    manifest=json.loads(DONOR_MANIFEST.read_text())['files']
    if not isinstance(manifest,dict) or len(manifest)!=963:raise RuntimeError('unexpected_source_manifest')
    changes=json.loads(PATCH_MANIFEST_BYTES)['files']
    expected={'hivezilla/stream-relay/src/publisher.rs'}
    if set(changes)!=expected:raise RuntimeError('unexpected_patch_scope')
    patched_paths=set(re.findall(r'^\+\+\+ b/(.+)$',PATCH.decode(),re.M))
    if patched_paths!=expected:raise RuntimeError('unexpected_patch_file_headers')
    STAGE.mkdir();PROVIDER.mkdir();TARGET.mkdir();(TARGET/'tmp').mkdir()
    REPORT.mkdir(parents=True,exist_ok=True)
    state['admission_free_disk_bytes']=available
    state['toolchain']={b:subprocess.check_output([str(TOOL_BIN/b),'--version'],text=True).strip() for b in ('rustc','cargo')}
    publish()
    for rel,h in manifest.items():
        p=Path(rel)
        if p.is_absolute() or '..' in p.parts:raise RuntimeError('unsafe_manifest_path')
        src=DONOR/p;dest=PROVIDER/p
        if src.is_symlink() or not src.is_file() or digest(src)!=h:raise RuntimeError('donor_file_changed:'+rel)
        dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,dest)
        if digest(dest)!=h:raise RuntimeError('source_copy_hash_mismatch:'+rel)
    (STAGE/'publisher-status.patch').write_bytes(PATCH)
    (STAGE/'PATCH-MANIFEST.json').write_bytes(PATCH_MANIFEST_BYTES)
    (REPORT/'publisher-status.patch').write_bytes(PATCH)
    (REPORT/'PATCH-MANIFEST.json').write_bytes(PATCH_MANIFEST_BYTES)
    (REPORT/'SOURCE-BEFORE.json').write_bytes(DONOR_MANIFEST.read_bytes())
    for rel,v in changes.items():
        if digest(PROVIDER/rel)!=v['before_sha256']:raise RuntimeError('patch_before_hash_mismatch:'+rel)
        (PROVIDER/rel).chmod(0o644)
    with (REPORT/'patch.log').open('xb') as log:
        subprocess.run(['patch','--batch','--forward','-p1','-i',str(STAGE/'publisher-status.patch')],cwd=PROVIDER,stdout=log,stderr=subprocess.STDOUT,check=True)
    found={str(p.relative_to(PROVIDER)) for p in PROVIDER.rglob('*') if p.is_file()}
    if found!=set(manifest):raise RuntimeError('unexpected_unlisted_provider_file')
    after={}
    for rel,h in manifest.items():
        wanted=changes[rel]['after_sha256'] if rel in changes else h
        if digest(PROVIDER/rel)!=wanted:raise RuntimeError('unexpected_source_change:'+rel)
        after[rel]=wanted
        (PROVIDER/rel).chmod(0o444)
    for d in sorted([p for p in PROVIDER.rglob('*') if p.is_dir()],key=lambda p:len(p.parts),reverse=True):d.chmod(0o555)
    PROVIDER.chmod(0o555)
    if after['hivezilla/stream-relay/src/bank_server.rs']!='120feaed48897c99512e1a24e2bb013053fc9f9dbcd17c2c6972339b16717b98' or after['hivezilla/stream-relay/src/bank_store.rs']!='cf52f6d55e2d72b1de4454cc4577119b0cf063e7aafd3493193d28a488a67c59':raise RuntimeError('status_cadence_fix_changed')
    source={'schema':'blockzilla-publisher-status-source-v1','donor':str(DONOR),'donor_manifest_sha256':DONOR_SHA,'patch_sha256':PATCH_SHA,'patch_manifest_sha256':PATCH_MANIFEST_SHA,'changed_files':changes,'file_count':len(after),'files':after}
    save(REPORT/'SOURCE.json',source)
    state['source_manifest_sha256']=digest(REPORT/'SOURCE.json')
    state['source_files']=len(after)
    graph=[p for p in after if any(p.startswith(d+'/src/') and p.endswith('.rs') for d in ('hivezilla/stream-relay','hivezilla/object-store','crates/blockzilla-bank-stream-v2'))]+['Cargo.toml','hivezilla/stream-relay/Cargo.toml','hivezilla/stream-relay/Cargo.lock','hivezilla/object-store/Cargo.toml','crates/blockzilla-bank-stream-v2/Cargo.toml']
    if len(graph)!=34:raise RuntimeError('unexpected_dependency_graph_size')
    save(REPORT/'GRAPH.json',{'files':{p:{'before_sha256':manifest[p],'after_sha256':after[p]} for p in sorted(graph)},'file_count':34,'changed_files':sorted(changes)})
    state['graph_manifest_sha256']=digest(REPORT/'GRAPH.json')
    env={'HOME':'/home/ubuntu','PATH':str(TOOL_BIN)+':/usr/bin:/bin','CARGO_HOME':'/home/ubuntu/.cargo','LANG':'C.UTF-8','CARGO_TARGET_DIR':str(TARGET),'CARGO_BUILD_JOBS':'4','RUSTFLAGS':FLAGS,'TMPDIR':str(TARGET/'tmp')}
    run_phase('TESTING',['test','--locked','--offline','-j','4'],'lib-tests.log',env)
    tests=(REPORT/'lib-tests.log').read_text()
    results=[(int(a),int(b)) for a,b in re.findall(r'test result: ok\. (\d+) passed; (\d+) failed;',tests)]
    if not results or sum(a for a,b in results)<44 or any(b for a,b in results):raise RuntimeError('expected_transport_tests_not_found')
    required=['publisher::tests::cancelled_object_upload_joins_without_starting_manifest_or_head', 'publisher::tests::final_status_write_failure_after_remote_head_does_not_commit', 'publisher::tests::initial_status_write_failure_starts_no_remote_work', 'publisher::tests::remote_failure_joins_before_failed_status_and_keeps_intent', 'publisher::tests::slow_batch_log_is_bounded_and_only_reports_completed_slow_batches', 'publisher::tests::status_write_failure_during_head_readback_does_not_commit', 'publisher::tests::upload_status_is_live_during_blocked_objects_without_advancing_checkpoint', 'publisher::tests::upload_status_is_live_during_head_readback_without_advancing_checkpoint']
    for name in required:
        if 'test '+name+' ... ok' not in tests:raise RuntimeError('required_regression_not_passed:'+name)
    publish(tests_passed=True,tests_count=sum(a for a,b in results),tests_failed=0,required_regression_tests=required)
    run_phase('BUILDING',['build','--release','--bin','hivezilla-stream','--locked','--offline','-j','4'],'release-build.log',env)
    for rel,h in after.items():
        if digest(PROVIDER/rel)!=h:raise RuntimeError('frozen_source_changed:'+rel)
    binary=TARGET/'release/hivezilla-stream'
    if not binary.is_file():raise RuntimeError('built_binary_missing')
    binary_sha=digest(binary)
    release=ROOT/'releases'/('publisher-status-20261018-'+PATCH_SHA[:8]+'-'+binary_sha[:12])
    release.mkdir()
    shutil.copy2(binary,release/'hivezilla-stream');(release/'hivezilla-stream').chmod(0o555)
    if digest(release/'hivezilla-stream')!=binary_sha:raise RuntimeError('release_copy_hash_mismatch')
    state.update(state='READY_NOT_ACTIVE',release=str(release),binary=str(release/'hivezilla-stream'),binary_sha256=binary_sha,completed_unix_ms=time.time_ns()//1000000,free_disk_bytes=free(),target_allocated_bytes=target_bytes())
    save(release/'BUILD-PROVENANCE.json',state)
    for name in ('SOURCE.json','SOURCE-BEFORE.json','GRAPH.json','PATCH-MANIFEST.json','publisher-status.patch'):shutil.copy2(REPORT/name,release/name)
    release_files={p.name:{'sha256':digest(p),'bytes':p.stat().st_size} for p in release.iterdir() if p.is_file()}
    save(release/'MANIFEST.json',{'schema':'blockzilla-publisher-status-release-v1','state':'READY_NOT_ACTIVE','binary_sha256':binary_sha,'source_manifest_sha256':state['source_manifest_sha256'],'patch_sha256':PATCH_SHA,'files':release_files})
    state['release_manifest_sha256']=digest(release/'MANIFEST.json')
    for p in release.iterdir():
        if p.name!='hivezilla-stream':p.chmod(0o444)
    release.chmod(0o555)
    publish()

try:
    main()
except BaseException as error:
    if REPORT.exists() and STAGE.exists():
        state.update(error_type=type(error).__name__,error=str(error),completed_unix_ms=time.time_ns()//1000000)
        publish(state='FAILED')
    print(type(error).__name__+': '+str(error),file=sys.stderr,flush=True)
    raise
